arguments.command:
cd /tmp/vally-eval-trial-TvMqcP && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
mkdir -p tests/CheckoutPricing.IntegrationTests/Checkout && cat > tests/CheckoutPricing.IntegrationTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var total = new CheckoutPricing.Application.Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests --filter LoyaltyDiscountTests 2>&1 | tail -20

